<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>2048 Game</title>
    <style>
        :root {
            --bg-color: #121212;
            --board-bg: #3d3d3d;
            --tile-bg: #2d2d2d;
            --text-color: #ffffff;
            --accent: #4caf50;
        }
        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            user-select: none;
        }
        h1 { margin: 0 0 10px 0; }
        #score {
            font-size: 1.5rem;
            font-weight: bold;
            margin-bottom: 15px;
        }
        #game-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 15px;
        }
        #board {
            display: grid;
            grid-template-columns: repeat(4, 80px);
            grid-template-rows: repeat(4, 80px);
            gap: 10px;
            background-color: var(--board-bg);
            padding: 10px;
            border-radius: 8px;
        }
        .tile {
            background-color: var(--tile-bg);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
            font-weight: bold;
            border-radius: 4px;
            transition: all 0.1s ease;
        }
        #reset {
            padding: 10px 20px;
            background-color: var(--accent);
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 1rem;
        }
        #reset:hover { opacity: 0.9; }
        .tile-2 { background: #eee4da; color: #776e65; }
        .tile-4 { background: #ede0c8; color: #776e65; }
        .tile-8 { background: #f2b179; color: #f9f6f2; }
        .tile-16 { background: #f59563; color: #f9f6f2; }
        .tile-32 { background: #f67c5f; color: #f9f6f2; }
        .tile-64 { background: #f65e3b; color: #f9f6f2; }
        .tile-128 { background: #edcf72; color: #f9f6f2; }
        .tile-256 { background: #edcc61; color: #f9f6f2; }
        .tile-512 { background: #edc850; color: #f9f6f2; }
        .tile-1024 { background: #edc53f; color: #f9f6f2; }
        .tile-2048 { background: #edc22e; color: #f9f6f2; }
    </style>
</head>
<body>

<div id="game-container">
    <h1>2048</h1>
    <div id="score">Score: 0</div>
    <button id="reset">New Game</button>
    <div id="board"></div>
</div>

<script>
const gameInternal = {
    board: Array(4).fill().map(() => Array(4).fill(0)),
    score: 0,
    size: 4
};

// API Object
window.game = {
    size: 4,
    reset() {
        for (let i = 0; i < 4; i++) {
            for (let j = 0; j < 4; j++) {
                gameInternal.board[i][j] = 0;
            }
        }
        gameInternal.score = 0;
        spawnTile();
        spawnTile();
        render();
    },
    move(dir) {
        if (processMove(dir)) {
            spawnTile();
            render();
            return true;
        }
        return false;
    },
    board() {
        return JSON.parse(JSON.stringify(gameInternal.board));
    },
    setBoard(arr) {
        for (let i = 0; i < 4; i++) {
            for (let j = 0; j < 4; j++) {
                gameInternal.board[i][j] = arr[i][j];
            }
        }
        gameInternal.score = 0;
        render();
    },
    score() {
        return gameInternal.score;
    }
};

// Logic Helpers
function spawnTile() {
    const empty = [];
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (gameInternal.board[i][j] === 0) empty.push({r: i, c: j});
        }
    }
    if (empty.length > 0) {
        const spot = empty[Math.floor(Math.random() * empty.length)];
        gameInternal.board[spot.r][spot.c] = Math.random() < 0.9 ? 2 : 4;
    }
}

function getGrid(direction) {
    const g = JSON.parse(JSON.stringify(gameInternal.board));
    if (direction === 'left') return g;
    if (direction === 'right') return g.map(row => row.reverse());
    if (direction === 'up') return g[0].map((_, c) => g.map(row => row[c]));
    if (direction === 'down') {
        const up = g[0].map((_, c) => g.map(row => row[c]));
        return up.map(col => col.reverse());
    }
}

function setGrid(direction, grid) {
    if (direction === 'left') return;
    if (direction === 'right') grid.forEach(r => r.reverse());
    if (direction === 'up') {
        for (let c = 0; c < 4; c++) {
            for (let r = 0; r < 4; r++) gameInternal.board[r][c] = grid[r][c];
        }
    } else if (direction === 'down') {
        const up = grid.map(col => col.reverse());
        for (let c = 0; c < 4; c++) {
            for (let r = 0; r < 4; r++) gameInternal.board[r][c] = up[r][c];
        }
    }
}

function processMove(direction) {
    const grid = getGrid(direction);
    const oldGrid = JSON.parse(JSON.stringify(grid));
    let changed = false;
    gameInternal.score = 0;

    for (let i = 0; i < 4; i++) {
        let row = grid[i].filter(v => v); // remove 0s
        for (let j = 0; j < row.length - 1; j++) {
            if (row[j] === row[j+1]) {
                row[j] *= 2;
                gameInternal.score += row[j];
                row.splice(j+1, 1);
                changed = true;
            }
        }
        while (row.length < 4) row.push(0);
        if (row.some((v, idx) => v !== oldGrid[i][idx])) changed = true;
        grid[i] = row;
    }
    if (changed) setGrid(direction, grid);
    return changed;
}

// Rendering
function render() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            const val = gameInternal.board[i][j];
            const div = document.createElement('div');
            div.className = `tile tile-${val}`;
            div.textContent = val > 0 ? val : '';
            boardEl.appendChild(div);
        }
    }
    document.getElementById('score').textContent = `Score: ${gameInternal.score}`;
}

// Listeners
document.getElementById('reset').addEventListener('click', () => game.reset());
document.addEventListener('keydown', (e) => {
    const key = e.key.toLowerCase();
    if (['arrowup','arrowdown','arrowleft','arrowright'].includes(key)) {
        e.preventDefault();
        const dirs = { 'arrowup': 'up', 'arrowdown': 'down', 'arrowleft': 'left', 'arrowright': 'right' };
        game.move(dirs[key]);
    }
});

game.reset();
</script>
</body>
</html>
